# Let's use a distance encoding in SAT.
# Variables:
# e(i,j) for i < j
# d2(i,j) for i < j
# d3(i,j) for i < j
# d4(i,j) for i < j
# Actually, we can just use directed distance variables from a root? No, we need all pairs.
# Let's write a python script to generate the CNF and solve it with Glucose4.
code = """
from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType

n = 21
solver = Glucose4()

var_counter = 1
def new_var():
    global var_counter
    v = var_counter
    var_counter += 1
    return v

e = {}
for i in range(n):
    for j in range(i+1, n):
        e[(i,j)] = new_var()

def get_e(i, j):
    if i == j: return None
    if i < j: return e[(i,j)]
    return e[(j,i)]

d2 = {}
for i in range(n):
    for j in range(i+1, n):
        d2[(i,j)] = new_var()

def get_d2(i, j):
    if i == j: return None
    if i < j: return d2[(i,j)]
    return d2[(j,i)]

d3 = {}
for i in range(n):
    for j in range(i+1, n):
        d3[(i,j)] = new_var()

def get_d3(i, j):
    if i == j: return None
    if i < j: return d3[(i,j)]
    return d3[(j,i)]

# d2(i,j) <-> exists k, e(i,k) and e(k,j)
for i in range(n):
    for j in range(i+1, n):
        # d2(i,j) -> OR_k (e(i,k) and e(k,j))
        # not d2(i,j) or e(i,k1) and e(k1,j) or ...
        # This is: for all k, e(i,k) and e(k,j) -> d2(i,j)
        for k in range(n):
            if k != i and k != j:
                solver.add_clause([-get_e(i,k), -get_e(k,j), get_d2(i,j)])

        # d2(i,j) -> OR_k (e(i,k) and e(k,j))
        clause = [-get_d2(i,j)]
        for k in range(n):
            if k != i and k != j:
                # We need auxiliary variables for the AND
                and_var = new_var()
                solver.add_clause([-and_var, get_e(i,k)])
                solver.add_clause([-and_var, get_e(k,j)])
                solver.add_clause([and_var, -get_e(i,k), -get_e(k,j)])
                clause.append(and_var)
        solver.add_clause(clause)

# no 3-cycle: e(i,j) -> not d2(i,j)
for i in range(n):
    for j in range(i+1, n):
        solver.add_clause([-get_e(i,j), -get_d2(i,j)])

# no 4-cycle: at most one k such that e(i,k) and e(k,j)
for i in range(n):
    for j in range(i+1, n):
        for k1 in range(n):
            if k1 == i or k1 == j: continue
            for k2 in range(k1+1, n):
                if k2 == i or k2 == j: continue
                solver.add_clause([-get_e(i,k1), -get_e(k1,j), -get_e(i,k2), -get_e(k2,j)])

# d3(i,j) <-> exists k, d2(i,k) and e(k,j)
for i in range(n):
    for j in range(i+1, n):
        for k in range(n):
            if k != i and k != j:
                solver.add_clause([-get_d2(i,k), -get_e(k,j), get_d3(i,j)])

        clause = [-get_d3(i,j)]
        for k in range(n):
            if k != i and k != j:
                and_var = new_var()
                solver.add_clause([-and_var, get_d2(i,k)])
                solver.add_clause([-and_var, get_e(k,j)])
                solver.add_clause([and_var, -get_d2(i,k), -get_e(k,j)])
                clause.append(and_var)
        solver.add_clause(clause)

# no 5-cycle: d2(i,j) -> not d3(i,j)
for i in range(n):
    for j in range(i+1, n):
        solver.add_clause([-get_d2(i,j), -get_d3(i,j)])

# no 6-cycle: at most one k such that d2(i,k) and e(k,j)
for i in range(n):
    for j in range(i+1, n):
        for k1 in range(n):
            if k1 == i or k1 == j: continue
            for k2 in range(k1+1, n):
                if k2 == i or k2 == j: continue
                solver.add_clause([-get_d2(i,k1), -get_e(k1,j), -get_d2(i,k2), -get_e(k2,j)])

# no 7-cycle: e(i,j) -> not (exists k, d3(k,i) and d3(k,j))
for i in range(n):
    for j in range(i+1, n):
        for k in range(n):
            if k != i and k != j:
                solver.add_clause([-get_e(i,j), -get_d3(k,i), -get_d3(k,j)])

# at least 40 edges
edge_vars = [e[(i,j)] for i in range(n) for j in range(i+1, n)]
cnf = CardEnc.atleast(lits=edge_vars, bound=40, encoding=EncType.seqcounter, vpool=None)
for clause in cnf.clauses:
    # We need to shift variables if they overlap, but CardEnc uses its own pool?
    # Actually, CardEnc uses variables starting from max(edge_vars) + 1 if vpool is None.
    # Let's just use a proper vpool.
    pass

"""
